  function openDocument(name){if((activeDoc||profileDraft)&&!confirmDiscardDoc())return;const id=prefs.activeAgent;activeDoc={id,name,original:getDoc(id,name),dirty:false};const pane=byId('pane-content');pane.innerHTML=`<div class="doc-editor"><label for="doc-textarea">${esc(name)} · ${esc(agentById(id).name)}</label><textarea id="doc-textarea" spellcheck="false"></textarea><div class="doc-actions"><button class="button-secondary" id="cancel-doc" type="button">Cancel</button><button class="button-primary" id="save-doc" type="button">Save</button></div><span class="doc-status" id="doc-status" role="status"></span><button class="button-secondary" id="back-doc" type="button" style="margin-top:12px">Back to agent</button></div>`;byId('doc-textarea').value=activeDoc.original;byId('doc-textarea').oninput=()=>activeDoc.dirty=byId('doc-textarea').value!==activeDoc.original;byId('save-doc').onclick=()=>{docs[id][name]=byId('doc-textarea').value;activeDoc.original=docs[id][name];activeDoc.dirty=false;saveDocs();byId('doc-status').textContent='Saved locally.';};byId('cancel-doc').onclick=()=>{activeDoc=null;renderAgentPane();};byId('back-doc').onclick=()=>{if(confirmDiscardDoc())renderAgentPane();};byId('doc-textarea').focus();}
