  function openPane(view='agent'){if((activeDoc||profileDraft)&&!confirmDiscardDoc())return;if(paneView!==view)resetToolContext();if(byId('right-pane').hidden)paneOpener=document.activeElement;paneView=view;byId('right-pane').hidden=false;syncPaneModal();byId('pane-title').textContent=view==='agent'?'Agent':view[0].toUpperCase()+view.slice(1);all('[data-pane]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.pane===view)));if(view==='agent')renderAgentPane();else if(view==='artifacts')renderArtifactsPane();else renderToolPane(view);}
